-- Nobita
-- Khong sua file nay. Moi thay doi lam hong bo giai ma.
local _runtpl = 53
local _kenblo = 29
local _mqitjc = 166
local _mmlmvc = ""

local _dcmrjs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _uqpfhb(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _cidraj(d)
	d = d:gsub("[^" .. _dcmrjs .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_dcmrjs:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _rgcard = _cidraj(_mmlmvc)
local _fjlqme = { _runtpl, _kenblo, _mqitjc }
local _rpcngu = {}
for i = 1, #_rgcard do
	_rpcngu[i] = string.char(_uqpfhb(_rgcard:byte(i), _fjlqme[(i - 1) % 3 + 1]))
end

local _aadyjz = load or loadstring
local _tqcwcn, _xhpdod = _aadyjz(table.concat(_rpcngu), "=w")
if not _tqcwcn then
	gg.alert("File hong: " .. tostring(_xhpdod))
	os.exit()
end
_tqcwcn()
